(function(){
  var SUPABASE_URL = '';
  var SUPABASE_ANON_KEY = 'local';
  fetch(SUPABASE_URL + '/rest/v1/map_settings?id=eq.1&select=gtm_container_id', {
    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + SUPABASE_ANON_KEY }
  }).then(function(r){ return r.json(); }).then(function(rows){
    var row = rows && rows[0];
    if(!row || !row.gtm_container_id) return;
    window.dataLayer = window.dataLayer || [];
    window.dataLayer.push({ 'gtm.start': new Date().getTime(), event: 'gtm.js' });
    var j = document.createElement('script');
    j.async = true;
    j.src = 'https://www.googletagmanager.com/gtm.js?id=' + row.gtm_container_id;
    document.head.appendChild(j);
    document.addEventListener('DOMContentLoaded', function(){
      var ifr = document.createElement('iframe');
      ifr.src = 'https://www.googletagmanager.com/ns.html?id=' + row.gtm_container_id;
      ifr.height = 0; ifr.width = 0; ifr.style.display = 'none'; ifr.style.visibility = 'hidden';
      var ns = document.createElement('noscript');
      ns.appendChild(ifr);
      document.body.insertBefore(ns, document.body.firstChild);
    });
  }).catch(function(){});
})();

(async function(){

  const SUPABASE_URL = '';
  const SUPABASE_ANON_KEY = 'local';
  const sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

  // ---------- Tag Manager event helper ----------
  // Pushes to the dataLayer directly (GTM's native format) instead of
  // calling gtag() — GTM's own snippet doesn't define a gtag() function,
  // only dataLayer.push(). Create a GA4 tag inside GTM triggered on a
  // custom event named "admin_action" to pick these up.
  function trackEvent(category, action, label){
    if(window.dataLayer){
      window.dataLayer.push({ event: 'admin_action', event_category: category, event_action: action, event_label: label });
    }
  }


  const statusPill = document.getElementById('status-pill');
  const statusText = document.getElementById('status-text');
  const modeNote = document.getElementById('mode-note');

  function setStatus(mode, msg, revertAfter){
    statusPill.className = mode;
    statusText.textContent = msg;
    clearTimeout(setStatus._t);
    if(revertAfter){
      setStatus._t = setTimeout(()=>{ statusPill.className=''; statusText.textContent = 'All changes saved — synced'; }, revertAfter);
    }
  }

  // Surfaces the real Supabase/Postgres error instead of a generic message,
  // so a failed save is actually diagnosable (expired session, RLS policy,
  // missing column, network block, etc.) instead of a dead end.
  function saveFailMsg(error){
    console.error('Supabase save error:', error);
    const detail = (error && (error.message || error.error_description || error.hint)) || 'unknown error';
    return 'Save failed — ' + detail;
  }

  let session = null;
  let isAuthed = false;

  const authOverlay = document.getElementById('auth-overlay');
  const authEmail = document.getElementById('auth-email');
  const authPassword = document.getElementById('auth-password');
  const authError = document.getElementById('auth-error');
  const authSubmit = document.getElementById('auth-submit');
  const authCancel = document.getElementById('auth-cancel');
  const authBtn = document.getElementById('btn-auth');

  // Signing in happens on the main site (super-admin), never in this editor.
  function goToSiteSignIn(){
    try{ (window.top || window).location.href = '/?admin=1'; }
    catch(e){ window.location.href = '/?admin=1'; }
  }
  function openAuthModal(){
    goToSiteSignIn();
    return;
    authError.textContent = '';
    authEmail.value = ''; authPassword.value = '';
    authOverlay.classList.add('open');
    authEmail.focus();
  }
  function closeAuthModal(){ authOverlay.classList.remove('open'); }
  authCancel.addEventListener('click', closeAuthModal);
  authOverlay.addEventListener('click', (e)=>{ if(e.target === authOverlay) closeAuthModal(); });

  authSubmit.addEventListener('click', async ()=>{
    const email = authEmail.value.trim();
    const password = authPassword.value;
    if(!email || !password){ authError.textContent = 'Enter both email and password.'; return; }
    authSubmit.disabled = true;
    const { error } = await sb.auth.signInWithPassword({ email, password });
    authSubmit.disabled = false;
    if(error){ authError.textContent = error.message; return; }
    closeAuthModal();
  });
  [authEmail, authPassword].forEach(el=> el.addEventListener('keydown', (e)=>{ if(e.key === 'Enter') authSubmit.click(); }));

  authBtn.addEventListener('click', async ()=>{
    if(isAuthed){
      if(confirm('Sign out?')) await sb.auth.signOut();
    } else {
      openAuthModal();
    }
  });

  function updateAuthUI(){
    if(isAuthed){
      authBtn.innerHTML = '<i class="ph ph-sign-out"></i> Sign out';
      authBtn.classList.add('on');
      modeNote.textContent = 'Your changes are live for everyone.';
    } else {
      authBtn.innerHTML = '<i class="ph ph-key"></i> Sign in';
      authBtn.classList.remove('on');
      modeNote.textContent = 'Session expired — sign in again to edit.';
    }
    // Signed in: hide the account area entirely (sign out lives in the super-admin menu).
    document.body.classList.toggle('editor-authed', isAuthed);
    document.querySelectorAll('.admin-only').forEach(el=>{
      el.style.display = isAuthed ? '' : 'none';
    });
  }

  sb.auth.onAuthStateChange((_event, sess)=>{
    session = sess;
    isAuthed = !!sess;
    updateAuthUI();
    refreshEditState();
  });

  function requireAuth(){
    if(!isAuthed){
      setStatus('error', 'Sign in to make changes', 2500);
      openAuthModal();
      return false;
    }
    return true;
  }

  // ---- Leads panel ----
  const leadsPanel = document.getElementById('leads-panel');
  const leadsBody = document.getElementById('leads-body');
  const btnLeads = document.getElementById('btn-leads');
  const leadsCloseBtn = document.getElementById('leads-close');

  function fmtLeadDate(iso){
    try{
      return new Date(iso).toLocaleString('en-IN', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });
    }catch(_e){ return iso || ''; }
  }

  async function loadLeads(){
    leadsBody.innerHTML = '<div id="leads-empty">Loading leads…</div>';
    const { data, error } = await sb.from('leads').select('*').order('created_at', { ascending:false });
    if(error){
      leadsBody.innerHTML = '<div id="leads-empty">Couldn\'t load leads — try again.</div>';
      return;
    }
    renderLeadsList(data || []);
  }

  function renderLeadsList(list){
    if(!list.length){
      leadsBody.innerHTML = '<div id="leads-empty">No leads yet.</div>';
      return;
    }
    leadsBody.innerHTML = list.map(lead => {
      const pin = pins.find(p => p.id === lead.pin_id);
      const projectLine = pin ? `<i class="ph ph-map-pin"></i> ${escapeHtml(pin.title || ('Pin #' + pin.number))}` : '<i class="ph ph-map-pin"></i> Project deleted';
      return `<div class="lead-card" data-lead-id="${lead.id}">
        <div class="lc-top">
          <span class="lc-name">${escapeHtml(lead.name || 'Unnamed')}</span>
          <span class="lc-role">${escapeHtml(lead.role || '')}</span>
        </div>
        <div class="lc-row"><i class="ph ph-whatsapp-logo"></i> ${escapeHtml(lead.whatsapp || '')}</div>
        <div class="lc-row"><i class="ph ph-envelope-simple"></i> ${escapeHtml(lead.email || '')}</div>
        <div class="lc-project">${projectLine}</div>
        <div class="lc-date">${fmtLeadDate(lead.created_at)}</div>
        <div class="lc-actions">
          <button class="lc-delete" data-lead-id="${lead.id}"><i class="ph ph-trash"></i> Delete</button>
        </div>
      </div>`;
    }).join('');

    leadsBody.querySelectorAll('.lc-delete').forEach(btn=>{
      btn.addEventListener('click', async ()=>{
        if(!requireAuth()) return;
        const id = btn.getAttribute('data-lead-id');
        if(!confirm('Delete this lead? This cannot be undone.')) return;
        btn.disabled = true;
        const { error } = await sb.from('leads').delete().eq('id', id);
        if(error){ setStatus('error', 'Delete failed — try again', 3000); btn.disabled = false; return; }
        const card = leadsBody.querySelector(`.lead-card[data-lead-id="${id}"]`);
        if(card) card.remove();
        if(!leadsBody.querySelector('.lead-card')) leadsBody.innerHTML = '<div id="leads-empty">No leads yet.</div>';
        setStatus('', 'All changes saved — synced', 1500);
      });
    });
  }

  function openLeadsPanel(){
    if(!requireAuth()) return;
    leadsPanel.classList.add('open');
    loadLeads();
  }
  function closeLeadsPanel(){ leadsPanel.classList.remove('open'); }

  btnLeads.addEventListener('click', openLeadsPanel);
  leadsCloseBtn.addEventListener('click', closeLeadsPanel);

  // ---- History / backup panel ----
  // Every edit or delete on a pin is captured automatically (via a database
  // trigger) into pins_history before it happens, so nothing is ever truly
  // lost — this panel just lists those snapshots and can put one back.
  const historyPanel = document.getElementById('history-panel');
  const historyBody = document.getElementById('history-body');
  const btnHistory = document.getElementById('btn-history');
  const historyCloseBtn = document.getElementById('history-close');

  function fmtHistoryDate(iso){
    try{
      return new Date(iso).toLocaleString('en-IN', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' });
    }catch(_e){ return iso || ''; }
  }

  // Newest 50 first; "Show more" loads 50 more each time.
  let historyLimit = 50;
  async function loadHistory(more){
    more = more === true;
    historyLimit = more ? historyLimit + 50 : 50;
    if(!more) historyBody.innerHTML = '<div id="history-empty">Loading history…</div>';
    const { data, error } = await sb.from('pins_history').select('*').order('changed_at', { ascending:false }).limit(historyLimit);
    if(error){
      historyBody.innerHTML = '<div id="history-empty">Couldn\'t load history — try again.</div>';
      return;
    }
    renderHistoryList(data || []);
  }

  function renderHistoryList(list){
    if(!list.length){
      historyBody.innerHTML = '<div id="history-empty">No history yet — it fills up as pins are edited or deleted.</div>';
      return;
    }
    historyBody.innerHTML = list.map(entry => {
      const row = entry.row_data || {};
      const stillExists = pins.some(p => p.id === entry.pin_id);
      const opLabel = entry.operation === 'delete' ? 'Deleted' : 'Edited';
      const opClass = entry.operation === 'delete' ? 'deleted' : 'updated';
      const restoreLabel = entry.operation === 'delete' ? 'Restore' : 'Revert to this';
      const disabledNote = (entry.operation === 'update' && !stillExists)
        ? '<div class="hi-row" style="color:var(--danger);">Pin no longer exists — restoring will recreate it.</div>' : '';
      return `<div class="history-card" data-history-id="${entry.history_id}">
        <div class="hi-top">
          <span class="hi-name">#${row.number != null ? row.number : '?'} ${escapeHtml(row.title || 'Untitled project')}</span>
          <span class="hi-op ${opClass}">${opLabel}</span>
        </div>
        ${disabledNote}
        <div class="hi-date">${fmtHistoryDate(entry.changed_at)}</div>
        <div class="hi-actions">
          <button class="hi-restore" data-history-id="${entry.history_id}"><i class="ph ph-arrow-counter-clockwise"></i> ${restoreLabel}</button>
        </div>
      </div>`;
    }).join('')
      + (list.length >= historyLimit ? '<button type="button" class="hi-more" id="history-more"><i class="ph ph-caret-down"></i> Show more</button>' : '')
      + '<div class="hi-backup-note"><i class="ph ph-shield-check"></i><span>This history is saved in the daily backups — see <b>Backups</b> in the admin panel.</span></div>';
    const moreBtn = document.getElementById('history-more');
    if(moreBtn) moreBtn.addEventListener('click', ()=>{ moreBtn.disabled = true; moreBtn.textContent = 'Loading…'; loadHistory(true); });

    historyBody.querySelectorAll('.hi-restore').forEach(btn=>{
      btn.addEventListener('click', async ()=>{
        if(!requireAuth()) return;
        const id = btn.getAttribute('data-history-id');
        if(!confirm('Restore this pin from history? This will overwrite the current pin (if it still exists) or recreate it.')) return;
        btn.disabled = true; btn.textContent = 'Restoring…';
        const { data, error } = await sb.rpc('restore_pin_from_history', { p_history_id: id });
        if(error){
          setStatus('error', 'Restore failed — try again', 4000);
          btn.disabled = false; btn.innerHTML = '<i class="ph ph-arrow-counter-clockwise"></i> Restore';
          return;
        }
        // Refresh the map's in-memory pin + marker for the restored row.
        const idx = pins.findIndex(p => p.id === data.id);
        if(idx >= 0){ pins[idx] = data; } else { pins.push(data); }
        if(pinMarkers.has(data.id)) map.removeLayer(pinMarkers.get(data.id));
        renderPin(data);
        setStatus('', 'Pin restored — synced', 2000);
        loadHistory();
      });
    });
  }

  function openHistoryPanel(){
    if(!requireAuth()) return;
    historyPanel.classList.add('open');
    loadHistory();
  }
  function closeHistoryPanel(){ historyPanel.classList.remove('open'); }

  btnHistory.addEventListener('click', openHistoryPanel);
  historyCloseBtn.addEventListener('click', closeHistoryPanel);

  // ---- Tracking & SEO panel ----
  const trackingPanel = document.getElementById('tracking-panel');
  const btnTracking = document.getElementById('btn-tracking');
  const trackingCloseBtn = document.getElementById('tracking-close');
  const tfGtm = document.getElementById('tf-gtm');
  const tfSearchConsole = document.getElementById('tf-search-console');
  const tfIntroVideo = document.getElementById('tf-intro-video');
  const btnSaveTracking = document.getElementById('btn-save-tracking');

  function openTrackingPanel(){
    if(!requireAuth()) return;
    tfGtm.value = currentSettings.gtm_container_id || '';
    tfSearchConsole.value = currentSettings.search_console_verification || '';
    tfIntroVideo.value = currentSettings.youtube_video_url || '';
    trackingPanel.classList.add('open');
  }
  function closeTrackingPanel(){ trackingPanel.classList.remove('open'); }

  btnTracking.addEventListener('click', openTrackingPanel);
  trackingCloseBtn.addEventListener('click', closeTrackingPanel);

  btnSaveTracking.addEventListener('click', async ()=>{
    if(!requireAuth()) return;
    const patch = {
      gtm_container_id: tfGtm.value.trim(),
      search_console_verification: tfSearchConsole.value.trim(),
      youtube_video_url: tfIntroVideo.value.trim()
    };
    const ok = await saveSettings(patch);
    if(ok) Object.assign(currentSettings, patch);
  });

  // scrollWheelZoom/touchZoom/doubleClickZoom set to 'center' — every zoom
  // gesture (wheel, pinch, double-click) keeps the current map centre fixed
  // instead of zooming toward the cursor/pinch point. The bottom-right +/-
  // control does this natively already, so this makes all zoom inputs consistent.
  // zoomSnap/zoomDelta of 0.25 means every zoom level is split into 4 smaller
  // steps — each +/- click, scroll notch, or pinch increment moves the map
  // only a little, instead of jumping a whole level at once.
  const map = L.map('map', {
    zoomControl:false,
    zoomSnap: 0.25,
    zoomDelta: 0.25,
    scrollWheelZoom:'center',
    touchZoom:'center',
    doubleClickZoom:'center'
  }).setView([18.5215, 73.9140], 14.5);
  map.attributionControl.setPrefix(
    '<a href="https://associatte.com" target="_blank" rel="noopener">Associatte.com</a> · ' +
    '<a href="privacy.html" target="_blank" rel="noopener">Privacy Policy</a> · <a href="disclaimer.html" target="_blank" rel="noopener">Disclaimer</a>'
  );
  L.control.zoom({position:'bottomright'}).addTo(map);

  // Lets the Google Places autocomplete script (near </body>) fly this
  // admin map to any real-world place — search "Mumbai", land there, then
  // use Add Project to drop a pin exactly where you need it.
  window.flyToSearchedPlace = function(lat, lng){
    map.flyTo([lat, lng], 15, { duration: 1.2 });
  };

  // ---------- "Show Cards Data" toggle ----------
  // Controls whether hovering a project pin shows its full details (price,
  // configuration, etc.) — the project name itself always stays visible on
  // hover either way, so nobody loses track of which pin is which.
  // Persisted with sessionStorage so it holds for the rest of this editing
  // session (tab), but resets to visible next time you open a fresh session.
  let showCardsData = sessionStorage.getItem('mm_showCardsData') !== '0';
  const cardsToggleInput = document.getElementById('toggle-cards-data');
  if(cardsToggleInput){
    cardsToggleInput.checked = showCardsData;
    cardsToggleInput.addEventListener('change', ()=>{
      showCardsData = cardsToggleInput.checked;
      sessionStorage.setItem('mm_showCardsData', showCardsData ? '1' : '0');
      reRenderMarkers();
      trackEvent('toolbar', 'toggle_cards_data', showCardsData ? 'on' : 'off');
    });
  }

  const baseTiles = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors',
    subdomains: 'abc', maxZoom: 19, crossOrigin: true
  }).addTo(map);
  const satTiles = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    attribution: 'Imagery &copy; Esri, Maxar, Earthstar Geographics',
    maxZoom: 20, crossOrigin: true
  });
  let activeTiles = baseTiles;
  let basemapMode = 'map';
  const basemapBtn = document.getElementById('btn-basemap');
  const mapContainer = document.getElementById('map');

  document.getElementById('loading').style.display = 'none';

  let boundary = [], boundaryLocked = false, markersLocked = false;
  let currentSettings = {}; // holds gtm_container_id, search_console_verification, etc.
  let pins = [], bridges = [], roads = [];

  function withTimeout(promise, ms, fallback){
    return Promise.race([
      promise,
      new Promise(resolve => setTimeout(()=> resolve(fallback), ms))
    ]);
  }

  const statusColor = {available:'#3f8f6b', sold:'#b5484c', construction:'#c98a2c', upcoming:'#3b6ea5'};
  const statusLabel = {available:'Available', sold:'Sold', construction:'Under Construction', upcoming:'Upcoming'};
  const pinScale = {small:0.78, medium:1, large:1.35};
  // Markers are ~32px, so they load a small cached thumbnail of the pin's
  // image (served by /api/pins/[id]/image) instead of the full-size file.
  const pinThumb = (src)=> (typeof src === 'string' && src.startsWith('/api/media/')) ? src + '&w=96' : src;
  function pinIcon(pin){
    const color = statusColor[pin.status] || statusColor.available;
    const head = pin.image
      ? `<img src="${pinThumb(pin.image)}" alt="">`
      : `<span class="glyph">${pin.number}</span>`;
    const badge = pin.image ? `<div class="pin-badge">${pin.number}</div>` : '';
    const radar = pin.highlighted ? '<div class="pin-radar"></div>' : '';
    const scale = pinScale[pin.size] || 1;
    return L.divIcon({
      className:'',
      html:`<div class="pin-wrap${pin.hidden ? ' is-hidden' : ''}" style="color:${color};transform:scale(${scale});" title="${pin.hidden ? 'Hidden from the public map' : ''}">
              ${radar}
              <div class="pin-circle" style="background:${color};">${head}</div>
              ${badge}
              ${pin.hidden ? '<div class="pin-hidden-badge"><i class="ph ph-eye-slash"></i></div>' : ''}
              <div class="pin-tail"></div>
              <div class="pin-ground"></div>
            </div>`,
      iconSize:[34,46], iconAnchor:[17,46], popupAnchor:[0,-44]
    });
  }
  const infraTypes = {
    bridge:          {emoji:'🌉', label:'Bridge',              color:'#3b6ea5'},
    highway_bridge:  {emoji:'🛣️', label:'Highway Bridge',       color:'#8f6f42'},
    flyover:         {emoji:'🎢', label:'Flyover',              color:'#7a5c9e'},
    bullet_train:    {emoji:'🚄', label:'Bullet Train Station', color:'#b5484c'},
    metro:           {emoji:'🚇', label:'Metro Station',        color:'#3f8f6b'},
    metro_line:      {emoji:'🚇', label:'Metro Line',           color:'#3f8f6b'},
    railway_station: {emoji:'🚉', label:'Railway Station',      color:'#5b7c99'},
    hotel:           {emoji:'🏨', label:'Hotel',                color:'#a0527a'},
    hospital:        {emoji:'🏥', label:'Hospital',             color:'#c0392b'},
    underpass:       {emoji:'🔽', label:'Underpass',            color:'#5c6670'},
    proposed_road:   {emoji:'🚧', label:'Proposed Road',        color:'#c98a2c'},
    school:          {emoji:'🏫', label:'School',                color:'#5c8a3f'},
    garden:          {emoji:'🌳', label:'Garden',                color:'#22c55e'}
  };
  const infraSizes = {small:{px:28, font:14}, medium:{px:38, font:19}, large:{px:50, font:25}};

  const builtInInfraTypeKeys = new Set(Object.keys(infraTypes));

  function renderCustomTypesLegend(){
    const el = document.getElementById('legend-custom-types');
    if(!el) return;
    const rows = Object.keys(infraTypes)
      .filter(key => !builtInInfraTypeKeys.has(key))
      .map(key => `${escapeHtml(infraTypes[key].emoji)} ${escapeHtml(infraTypes[key].label)}`);
    el.innerHTML = rows.length
      ? `<div class="divider"></div><div class="row">${rows.join(' &nbsp; ')}</div>`
      : '';
  }

  // How many bridges/roads currently point at a given custom infra type key —
  // shown as a warning before deleting one, since deleting doesn't touch those records.
  function customTypeUsageCount(key){
    return bridges.filter(b => b.type === key).length + roads.filter(r => r.type === key).length;
  }

  // Small management list under "Create Type" so duplicate/unused custom types
  // (e.g. re-adding "Helipad" several times) can be cleaned up without needing
  // direct database access.
  function renderCustomTypesManageList(){
    const el = document.getElementById('custom-types-manage');
    if(!el) return;
    const keys = Object.keys(infraTypes).filter(k => !builtInInfraTypeKeys.has(k));
    if(!keys.length){ el.innerHTML = ''; return; }
    el.innerHTML = `<label style="display:block;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.5px;color:var(--text-secondary);margin-bottom:6px;">Custom Types</label>` +
      keys.map(k => {
        const t = infraTypes[k];
        const usage = customTypeUsageCount(k);
        return `<div class="custom-type-row" style="display:flex;align-items:center;justify-content:space-between;padding:6px 8px;border:1px solid var(--border-default);border-radius:var(--radius);margin-bottom:6px;font-size:12.5px;">
          <span>${t.emoji || '📍'} ${escapeHtml(t.label)}${usage ? ` <span style="color:var(--text-secondary);">(${usage} in use)</span>` : ''}</span>
          <button type="button" class="ct-delete" data-type-key="${k}" style="border:none;background:none;color:var(--danger);cursor:pointer;font-size:14px;padding:2px 4px;" title="Delete this type"><i class="ph ph-trash"></i></button>
        </div>`;
      }).join('');
    el.querySelectorAll('.ct-delete').forEach(btn=>{
      btn.addEventListener('click', async ()=>{
        if(!requireAuth()) return;
        const key = btn.getAttribute('data-type-key');
        const t = infraTypes[key];
        const usage = customTypeUsageCount(key);
        const label = t ? t.label : key;
        const msg = usage
          ? `"${label}" is currently used by ${usage} marker(s)/road(s). Delete the type anyway? Those items will fall back to the default style.`
          : `Delete the "${label}" type? This can't be undone.`;
        if(!confirm(msg)) return;
        btn.disabled = true;
        const { error } = await sb.from('infra_types').delete().eq('key', key);
        if(error){ setStatus('error', 'Delete failed — try again', 3000); btn.disabled = false; return; }
        delete infraTypes[key];
        const select = document.getElementById('field-infra-type');
        if(select){
          const opt = select.querySelector(`option[value="${CSS.escape(key)}"]`);
          if(opt) opt.remove();
        }
        renderCustomTypesLegend();
        renderCustomTypesManageList();
        setStatus('', 'All changes saved — synced', 1500);
      });
    });
  }

  // Adds a custom infra type (from Supabase, or freshly created by the user) into the
  // running infraTypes lookup, the dropdown, and the map legend. Never touches the
  // built-in types above.
  // Wrapped defensively: if the dropdown markup is ever out of sync, this must never be
  // able to crash page load and take the pins/markers down with it.
  function registerCustomInfraType(ct, selectAfter){
    try{
      infraTypes[ct.key] = { emoji: ct.emoji || '📍', label: ct.label, color: ct.color || '#3b6ea5' };
      renderCustomTypesLegend();
      const select = document.getElementById('field-infra-type');
      if(!select) return;
      if(select.querySelector(`option[value="${CSS.escape(ct.key)}"]`)) return;
      const opt = document.createElement('option');
      opt.value = ct.key;
      opt.textContent = `${ct.emoji || '📍'} ${ct.label}`;
      const addNewOpt = select.querySelector('option[value="__add_new__"]');
      const divider = addNewOpt ? addNewOpt.previousElementSibling : null;
      if(divider) select.insertBefore(opt, divider);
      else select.appendChild(opt);
      if(selectAfter) select.value = ct.key;
    }catch(err){
      console.error('registerCustomInfraType failed (non-fatal):', err);
    }
  }

  function infraIcon(b){
    const meta = infraTypes[b.type] || infraTypes.bridge;
    const sz = infraSizes[b.size] || infraSizes.medium;
    const color = b.color || meta.color;
    const inner = b.icon_image ? `<img src="${pinThumb(b.icon_image)}" alt="">` : meta.emoji;
    return L.divIcon({
      className:'',
      html:`<div class="infra-pin" style="width:${sz.px}px;height:${sz.px}px;background:${color};font-size:${sz.font}px;">${inner}</div>`,
      iconSize:[sz.px, sz.px], iconAnchor:[sz.px/2, sz.px], popupAnchor:[0, -sz.px+2]
    });
  }

  function infraHoverContent(b){
    const meta = infraTypes[b.type] || infraTypes.bridge;
    const color = b.color || meta.color;
    const title = (b.title && b.title.trim()) ? b.title.trim() : meta.label;
    const emojiInner = b.icon_image
      ? `<img src="${b.icon_image}" alt="">`
      : meta.emoji;
    const notesHtml = (b.notes && b.notes.trim())
      ? `<p class="ihc-notes">${escapeHtml(b.notes.trim())}</p>`
      : `<p class="ihc-empty">No notes added yet</p>`;
    return `<div class="infra-hover-card">
      <div class="ihc-header" style="background:${color};">
        <div class="ihc-emoji">${emojiInner}</div>
        <div class="ihc-title-wrap">
          <p class="ihc-title">${escapeHtml(title)}</p>
          <div class="ihc-type">${escapeHtml(meta.label)}</div>
        </div>
      </div>
      <div class="ihc-body">${notesHtml}</div>
      <div class="ihc-footer"><i class="ph ph-hand-pointing" style="font-size:12px;"></i> Click to edit · Drag to move</div>
    </div>`;
  }

  function roadHoverContent(r){
    const meta = infraTypes[r.type] || infraTypes.proposed_road;
    const color = r.color || meta.color;
    const title = (r.title && r.title.trim()) ? r.title.trim() : meta.label;
    const notesHtml = (r.notes && r.notes.trim())
      ? `<p class="rhc-notes">${escapeHtml(r.notes.trim())}</p>`
      : `<p class="rhc-empty">No notes added yet</p>`;
    const pointCount = r.points ? r.points.length : 0;
    return `<div class="road-hover-card">
      <div class="rhc-header" style="background:${color};">
        <div class="rhc-emoji">${meta.emoji}</div>
        <div style="flex:1;min-width:0;">
          <p class="rhc-title">${escapeHtml(title)}</p>
          <div class="rhc-type">${escapeHtml(meta.label)}</div>
        </div>
      </div>
      <div class="rhc-body">${notesHtml}</div>
      <div class="rhc-footer"><i class="ph ph-path" style="font-size:12px;"></i> ${pointCount} point${pointCount === 1 ? '' : 's'} · Click to edit</div>
    </div>`;
  }

  function escapeHtml(str){
    if(!str) return '';
    return String(str)
      .replace(/&/g,'&amp;')
      .replace(/</g,'&lt;')
      .replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;')
      .replace(/'/g,'&#39;');
  }

  async function loadAll(){
    const sessResult = await withTimeout(sb.auth.getSession(), 4000, { data: { session: null } });
    const [pinsRes, infraRes, roadsRes, settingsRes, customTypesRes] = await Promise.all([
      sb.from('pins').select('*').order('number', { ascending: true }),
      sb.from('infra_markers').select('*'),
      sb.from('roads').select('*'),
      sb.from('map_settings').select('*').eq('id', 1).single(),
      sb.from('infra_types').select('*').order('created_at', { ascending: true })
    ]);
    session = sessResult.data.session; isAuthed = !!session;
    pins = pinsRes.data || [];
    bridges = infraRes.data || [];
    roads = roadsRes.data || [];
    if(settingsRes.data){
      boundary = settingsRes.data.boundary || [];
      boundaryLocked = !!settingsRes.data.boundary_locked;
      markersLocked = !!settingsRes.data.markers_locked;
      currentSettings = settingsRes.data;
    }
    // Custom infra types added by the team (stored in Supabase). If this table doesn't
    // exist yet, or the fetch fails, everything else keeps working as before.
    try{
      if(!customTypesRes.error && customTypesRes.data){
        customTypesRes.data.forEach(ct => registerCustomInfraType(ct, false));
      }
      renderCustomTypesManageList();
    }catch(err){
      console.error('Custom infra type setup failed (non-fatal):', err);
    }
  }
  try{
    await loadAll();
  }catch(err){
    console.error('loadAll failed, falling back to empty state:', err);
    setStatus('error', 'Could not load latest data — check connection and refresh', 5000);
  }
  updateAuthUI();

  function setBasemapMode(mode){
    if(map.hasLayer(baseTiles)) map.removeLayer(baseTiles);
    if(map.hasLayer(satTiles)) map.removeLayer(satTiles);
    mapContainer.classList.remove('night-mode');
    basemapBtn.classList.remove('on');
    if(mode === 'map'){
      baseTiles.addTo(map); activeTiles = baseTiles;
      basemapBtn.innerHTML = '<i class="ph ph-globe-hemisphere-west"></i> Satellite';
    } else if(mode === 'satellite'){
      satTiles.addTo(map); activeTiles = satTiles;
      basemapBtn.innerHTML = '<i class="ph ph-moon"></i> Night'; basemapBtn.classList.add('on');
    } else {
      baseTiles.addTo(map); activeTiles = baseTiles;
      mapContainer.classList.add('night-mode');
      basemapBtn.innerHTML = '<i class="ph ph-map-trifold"></i> Map'; basemapBtn.classList.add('on');
    }
    basemapMode = mode;
  }
  basemapBtn.addEventListener('click', ()=>{
    setBasemapMode(basemapMode === 'map' ? 'satellite' : basemapMode === 'satellite' ? 'night' : 'map');
  });

  const boundaryPolygon = L.polygon(boundary, {
    color:'#e74c3c', weight:2.5, dashArray:'5,5', fillColor:'#e74c3c', fillOpacity:0.03,
    interactive:false
  }).addTo(map);

  let isEditingLocally = false;

  async function saveSettings(patch){
    setStatus('saving','Saving…');
    const { error } = await sb.from('map_settings').update(patch).eq('id', 1);
    if(error){ setStatus('error',saveFailMsg(error), 6000); return false; }
    setStatus('', 'All changes saved — synced', 1500);
    return true;
  }

  let vertexMarkers = [];
  function renderVertices(){
    vertexMarkers.forEach(m=>map.removeLayer(m));
    vertexMarkers = [];
    if(boundaryLocked || !isAuthed) return;
    boundary.forEach((coord, index)=>{
      const vm = L.marker(coord, {
        draggable: true,
        icon: L.divIcon({className:'', html:'<div class="vertex-dot"></div>', iconSize:[11,11], iconAnchor:[5,5]})
      }).addTo(map);
      vm.on('dragstart', ()=> isEditingLocally = true);
      vm.on('drag', e=>{
        const ll = e.target.getLatLng();
        boundary[index] = [ll.lat, ll.lng];
        boundaryPolygon.setLatLngs(boundary);
      });
      vm.on('dragend', async ()=>{ isEditingLocally = false; await saveSettings({boundary}); });
      vm.on('dblclick', async (e)=>{
        L.DomEvent.stop(e);
        if(boundary.length > 3){
