  function resizeImage(file, maxDim=720, quality=0.85){
    return new Promise((resolve, reject)=>{
      const reader = new FileReader();
      reader.onload = ()=>{
        const img = new Image();
        img.onload = ()=>{
          let w = img.width, h = img.height;
          if(w > h && w > maxDim){ h = Math.round(h * maxDim / w); w = maxDim; }
          else if(h > maxDim){ w = Math.round(w * maxDim / h); h = maxDim; }
          const canvas = document.createElement('canvas');
          canvas.width = w; canvas.height = h;
          canvas.getContext('2d').drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL('image/jpeg', quality));
        };
        img.onerror = reject;
        img.src = reader.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }


  const pinMarkers = new Map();
  const bridgeMarkers = new Map();
  // Per-pin state for the "Show/Hide Details" toggle on each project card —
  // keyed by pin id so it's remembered across re-renders in this session.
  // Independent from the global "Show Cards Data" switch, which controls
  // whether a card appears on hover at all.
  const cardDetailsCollapsed = new Map();

  function renderPin(pin){
    if(pinMarkers.has(pin.id)) map.removeLayer(pinMarkers.get(pin.id));
    const marker = L.marker([pin.lat, pin.lng], {draggable: isAuthed && !markersLocked, icon: pinIcon(pin)}).addTo(map);

    const color = statusColor[pin.status] || statusColor.available;
    const imgTag = pin.image ? `<img src="${pin.image}" alt="">` : '';
    // Global "Show Cards Data" OFF forces every card to its name-only view;
    // when ON, each card falls back to its own remembered collapsed state.
    const collapsed = !showCardsData || !!cardDetailsCollapsed.get(pin.id);
    const detailRows = [
      pin.price ? `<div class="hc-row"><span class="hc-label">Price</span><span>${escapeHtml(pin.price)}</span></div>` : '',
      `<div class="hc-row"><span class="hc-label">Type</span><span>${escapeHtml(pin.type || 'Residential')}</span></div>`,
      pin.configuration ? `<div class="hc-row"><span class="hc-label">Configuration</span><span>${escapeHtml(pin.configuration)}</span></div>` : '',
      pin.sqft ? `<div class="hc-row"><span class="hc-label">Sq Ft</span><span>${escapeHtml(pin.sqft)}</span></div>` : '',
      `<div class="hc-row"><span class="hc-label">Status</span><span class="hc-status" style="background:${color};">${statusLabel[pin.status] || 'Available'}</span></div>`
    ].filter(Boolean).join('');
    const hoverContent = `<div class="hover-card">${imgTag}<div class="hc-body">
        <div class="hc-header">
          <p class="hc-title">#${pin.number} ${escapeHtml(pin.title || 'Untitled project')}</p>
          <button type="button" class="hc-toggle${collapsed ? ' collapsed' : ''}" title="Show/hide details" aria-label="Show/hide details" aria-expanded="${collapsed ? 'false' : 'true'}">
            <i class="ph ph-caret-up"></i>
          </button>
        </div>
        <div class="hc-details${collapsed ? ' collapsed' : ''}">${detailRows}</div>
      </div></div>`;
    marker.bindPopup(hoverContent, {closeButton:false, autoClose:false, className:'pin-hover-popup', offset:[0,-4]});

    // Hover-intent: a short close delay so moving the cursor from the
    // marker into the open card (to click Show/Hide Details) doesn't
    // instantly close it. Cleared whenever the pointer re-enters either.
    let closeTimer = null;
    const scheduleClose = ()=>{ closeTimer = setTimeout(()=> marker.closePopup(), 200); };
    // The card always opens on hover — even with "Show Cards Data" off, the
    // project name stays visible; only the detail fields collapse.
    marker.on('mouseover', ()=> { clearTimeout(closeTimer); marker.openPopup(); });
    marker.on('mouseout', scheduleClose);
    marker.on('popupopen', (e)=>{
      const el = e.popup.getElement();
      if(!el || el.dataset.hoverBound) return;
      el.dataset.hoverBound = '1';
      el.addEventListener('mouseenter', ()=> clearTimeout(closeTimer));
      el.addEventListener('mouseleave', scheduleClose);
      const toggleBtn = el.querySelector('.hc-toggle');
      const detailsEl = el.querySelector('.hc-details');
      if(toggleBtn && detailsEl){
        toggleBtn.addEventListener('click', (ev)=>{
          L.DomEvent.stop(ev);
          const nowCollapsed = !detailsEl.classList.contains('collapsed');
          detailsEl.classList.toggle('collapsed', nowCollapsed);
          toggleBtn.classList.toggle('collapsed', nowCollapsed);
          toggleBtn.setAttribute('aria-expanded', nowCollapsed ? 'false' : 'true');
          cardDetailsCollapsed.set(pin.id, nowCollapsed);
          // Repositions the popup as its height animates open/closed.
          const popup = marker.getPopup();
          requestAnimationFrame(()=> popup.update());
          setTimeout(()=> popup.update(), 300);
          trackEvent('map', 'toggle_card_details', pin.title || ('#' + pin.number));
        });
      }
    });

    marker.on('dragstart', ()=> isEditingLocally = true);
    marker.on('dragend', async e=>{
      const ll = e.target.getLatLng();
      pin.lat = ll.lat; pin.lng = ll.lng;
      // Keep realtime reloads paused while the edit panel is still open,
      // otherwise the map would redraw underneath an unsaved form.
      isEditingLocally = sidebar.classList.contains('open');
      setStatus('saving','Saving…');
      const { error } = await sb.from('pins').update({lat: pin.lat, lng: pin.lng}).eq('id', pin.id);
      setStatus(error ? 'error' : '', error ? saveFailMsg(error) : 'Position saved — live on the map', 2000);
    });
    marker.on('click', ()=>{ marker.closePopup(); openSidebar('pin', pin.id);
      if(isAuthed && markersLocked) setStatus('error', 'Projects are locked — click "Unlock Projects" to move pins', 4000); trackEvent('map', 'click_pin', pin.title || ('#' + pin.number)); });
    pinMarkers.set(pin.id, marker);
  }
