  const roadWeights = {small:3, medium:5, large:8};
  const roadLayers = new Map();
  function isBridgeLike(type){ return type === 'bridge' || type === 'highway_bridge' || type === 'flyover'; }
  function removeRoad(id, alsoFromArray){
    const g = roadLayers.get(id);
    if(g){
      map.removeLayer(g.line);
      if(g.casing) map.removeLayer(g.casing);
      g.verts.forEach(v=>map.removeLayer(v));
      roadLayers.delete(id);
    }
    if(alsoFromArray){ roads = roads.filter(x=>x.id !== id); }
  }
  function renderRoad(r){
    removeRoad(r.id, false);
    const meta = infraTypes[r.type] || infraTypes.proposed_road;
    const color = r.color || meta.color;
    const weight = r.weight || 5;
    let casing = null;
    if(isBridgeLike(r.type)){
      casing = L.polyline(r.points, {
        color:'#ffffff', weight: weight + 6, opacity:0.9, lineJoin:'round', lineCap:'round', interactive:false
      }).addTo(map);
    }
    const isMetro = r.type === 'metro_line';
    const line = L.polyline(r.points, {
      color, weight: isMetro ? Math.min(weight, 3) : weight, opacity:0.95,
      dashArray: (r.type === 'proposed_road') ? '10,8' : (isMetro ? '7,5' : null),
      lineJoin:'round', lineCap:'round'
    }).addTo(map);
    line.bindPopup(roadHoverContent(r), {closeButton:false, className:'road-hover-popup'});
    line.on('mouseover', ()=> { if(showCardsData) line.openPopup(); });
    line.on('click', (e)=>{ L.DomEvent.stop(e); openSidebar('road', r.id); trackEvent('map', 'click_road', r.type || 'road'); });
    const verts = [];
    if(isAuthed && !markersLocked){
      r.points.forEach((pt, idx)=>{
        const vm = L.marker(pt, {draggable:true, icon: L.divIcon({className:'',
          html:`<div class="vertex-dot" style="background:${color}"></div>`, iconSize:[11,11], iconAnchor:[5,5]})}).addTo(map);
        vm.on('dragstart', ()=> isEditingLocally = true);
        vm.on('drag', e=>{ const ll = e.target.getLatLng(); r.points[idx] = [ll.lat, ll.lng]; line.setLatLngs(r.points); });
        vm.on('dragend', async ()=>{
          isEditingLocally = false;
          setStatus('saving','Saving…');
          const { error } = await sb.from('roads').update({points: r.points}).eq('id', r.id);
          setStatus(error ? 'error' : '', error ? saveFailMsg(error) : 'All changes saved — synced', 2000);
        });
        vm.on('dblclick', async (e)=>{
          L.DomEvent.stop(e);
          if(r.points.length > 2){
            r.points.splice(idx,1); renderRoad(r);
            await sb.from('roads').update({points: r.points}).eq('id', r.id);
          }
        });
        verts.push(vm);
      });
    }
    roadLayers.set(r.id, {line, casing, verts});
  }

  let drawMode = null, drawPoints = [], drawLine = null;
  const drawHint = document.getElementById('draw-hint');
  const drawHintText = document.getElementById('draw-hint-text');
  function startDraw(mode){
    if(!requireAuth()) return;
    cancelDraw();
    drawMode = mode; drawPoints = []; drawRedoStack = [];
    isEditingLocally = true;
    map.doubleClickZoom.disable();
    map.dragging.disable();
    map.getContainer().style.cursor = 'crosshair';

    let drawColor = '#c98a2c';
    let drawWeight = 3;
    let drawDash = '6,6';

    if (mode === 'boundary') {
      drawColor = '#e74c3c';
      drawHintText.textContent = 'Click, or click-and-drag, to trace the boundary — then Finish (min 3).';
    } else if (mode === 'metro_line') {
      drawColor = '#3f8f6b';
      drawWeight = 3;
      drawDash = '7,5';
      drawHintText.textContent = 'Click, or click-and-drag, to trace the metro line — then Finish (min 2 points).';
    } else {
      drawHintText.textContent = 'Click, or click-and-drag, to trace the road/line — then Finish (min 2 points).';
    }

    drawLine = L.polyline([], {color: drawColor, weight: drawWeight, dashArray: drawDash}).addTo(map);
    drawHint.style.display = 'flex';
  }
  let drawPointMarkers = [];
  function drawPointColor(){ 
    if (drawMode === 'boundary') return '#e74c3c';
    if (drawMode === 'metro_line') return '#3f8f6b';
    return '#c98a2c'; 
  }
  function addPointMarker(latlng){
    const m = L.circleMarker(latlng, {radius:5, color:'#fff', weight:2, fillColor: drawPointColor(), fillOpacity:1}).addTo(map);
    drawPointMarkers.push(m);
  }
  function clearPointMarkers(){
    drawPointMarkers.forEach(m=>map.removeLayer(m));
    drawPointMarkers = [];
  }
  function addDrawPoint(latlng){
    drawPoints.push([latlng.lat, latlng.lng]);
    drawLine.setLatLngs(drawPoints);
    drawRedoStack = [];
    addPointMarker(latlng);
  }
  let drawRedoStack = [];
  function undoDrawPoint(){
    if(!drawMode || drawPoints.length === 0) return;
    drawRedoStack.push(drawPoints.pop());
    drawLine.setLatLngs(drawPoints);
    const m = drawPointMarkers.pop();
    if(m) map.removeLayer(m);
  }
  function redoDrawPoint(){
    if(!drawMode || drawRedoStack.length === 0) return;
    const p = drawRedoStack.pop();
    drawPoints.push(p);
    drawLine.setLatLngs(drawPoints);
    addPointMarker(L.latLng(p[0], p[1]));
  }
  function cancelDraw(){
    if(drawLine){ map.removeLayer(drawLine); drawLine = null; }
    clearPointMarkers();
    drawMode = null; drawPoints = []; drawRedoStack = [];
    map.doubleClickZoom.enable();
    map.dragging.enable();
    map.getContainer().style.cursor = '';
    drawHint.style.display = 'none';
    isEditingLocally = false;
  }
  async function finishDraw(){
    const mode = drawMode;
    const pts = [];
    drawPoints.forEach(p=>{
      const last = pts[pts.length-1];
      if(!last || Math.abs(last[0]-p[0])>1e-7 || Math.abs(last[1]-p[1])>1e-7) pts.push(p);
    });
    cancelDraw();
    if(mode === 'boundary'){
      if(pts.length >= 3){
        boundary = pts;
        boundaryPolygon.setLatLngs(boundary);
        renderVertices();
        await saveSettings({boundary});
      } else { setStatus('error','Need at least 3 points for a boundary', 2000); }
    } else if(mode === 'road' || mode === 'metro_line'){
      if(pts.length >= 2){
        setStatus('saving','Saving…');
        const lineType = mode === 'metro_line' ? 'metro_line' : 'proposed_road';
        const lineColor = mode === 'metro_line' ? infraTypes.metro_line.color : infraTypes.proposed_road.color;
        const { data, error } = await sb.from('roads').insert({
          type: lineType, color: lineColor,
          weight: mode === 'metro_line' ? roadWeights.small : roadWeights.medium, title:'', notes:'', points: pts
        }).select().single();
        if(error){ setStatus('error',saveFailMsg(error), 6000); return; }
        roads.push(data);
        renderRoad(data);
        setStatus('', 'All changes saved — synced', 1500);
        openSidebar('road', data.id);
      } else { setStatus('error','Need at least 2 points for a line', 2000); }
    }
  }
  let isPointerDrawing = false;
  function pixelDistance(latlngA, latlngB){
    const pa = map.latLngToContainerPoint(latlngA);
    const pb = map.latLngToContainerPoint(latlngB);
    return pa.distanceTo(pb);
  }
  map.on('mousedown', (e)=>{
    if(!drawMode) return;
    isPointerDrawing = true;
    addDrawPoint(e.latlng);
  });
  map.on('mousemove', (e)=>{
    if(!drawMode || !isPointerDrawing) return;
    const last = drawPoints[drawPoints.length-1];
    if(!last || pixelDistance(L.latLng(last[0], last[1]), e.latlng) >= 8){
      addDrawPoint(e.latlng);
    }
  });
  map.on('mouseup', ()=>{ isPointerDrawing = false; });
  map.on('dblclick', (e)=>{ if(drawMode){ L.DomEvent.stop(e); finishDraw(); } });
  document.getElementById('draw-finish').addEventListener('click', finishDraw);
  document.getElementById('draw-cancel').addEventListener('click', cancelDraw);
  document.getElementById('draw-undo').addEventListener('click', undoDrawPoint);
  document.getElementById('draw-redo').addEventListener('click', redoDrawPoint);
  document.addEventListener('keydown', (e)=>{
    if(!drawMode) return;
    if(e.key === 'Enter') finishDraw();
    else if(e.key === 'Escape') cancelDraw();
    else if((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'z'){ e.preventDefault(); undoDrawPoint(); }
    else if((e.ctrlKey || e.metaKey) && (e.key.toLowerCase() === 'y' || (e.shiftKey && e.key.toLowerCase() === 'z'))){ e.preventDefault(); redoDrawPoint(); }
    else if(e.key === 'Backspace'){ e.preventDefault(); undoDrawPoint(); }
  });
  document.getElementById('btn-draw-road').addEventListener('click', ()=> startDraw('road'));
  document.getElementById('btn-draw-metro').addEventListener('click', ()=> startDraw('metro_line'));
  document.getElementById('btn-draw-boundary').addEventListener('click', ()=> startDraw('boundary'));

