  const RERA_HINT = 'Shown on the public card. For several phases, separate numbers with commas.';
  const normRera = (v)=> String(v || '').toUpperCase().split(/[,;\n]+/).map(x=> x.replace(/\s+/g, '')).filter(Boolean).join(', ');
  const RERA_LABEL = /\b(maha\s*)?rera\b/i;   // matches the old "Rera No" custom field
  function checkRera(){
    const parts = normRera(fRera.value).split(', ').filter(Boolean);
    const odd = parts.filter(x=> !/^P[A-Z]?\d{8,14}$/.test(x));
    reraHint.textContent = odd.length ? ('Check this number: ' + odd.join(', ') + ' — MahaRERA numbers look like P52100012345 or PM1261012600059.') : RERA_HINT;
