  // ---------- Custom fields ----------
  // Admin-defined extra fields beyond the standard list, each with its own
  // on/off switch. Held in memory while a pin's sidebar is open; saved to
  // the pin's custom_fields column (an array of {id,label,value,visible}).
  const wrapCustomFields = document.getElementById('wrap-custom-fields');
  const customFieldsList = document.getElementById('custom-fields-list');
  const btnAddCustomField = document.getElementById('btn-add-custom-field');
  let currentCustomFields = [];
  let cfIdCounter = 0;
  function renderCustomFieldsList(){
    customFieldsList.innerHTML = currentCustomFields.map(cf => `
      <div class="cf-row" data-cf-id="${cf.id}">
        <div class="cf-inputs">
          <input type="text" class="cf-label" placeholder="Field name (e.g. RERA No.)" value="${escapeHtml(cf.label || '')}">
