    `).join('');
    customFieldsList.querySelectorAll('.cf-remove').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const id = btn.closest('.cf-row').dataset.cfId;
        currentCustomFields = currentCustomFields.filter(cf => String(cf.id) !== id);
