  const CHIP_ICONS = {
    'Residential':'ph-house-line', 'Commercial':'ph-storefront', 'Plotting':'ph-grid-four',
    'Mixed-Use':'ph-buildings', 'Amenity':'ph-tree', 'Land Parcel':'ph-map-trifold'
