  function buildChipPicker(select){
    const picker = document.querySelector('.chip-picker[data-for="' + select.id + '"]');
    if(!picker) return;
    picker.innerHTML = '';
    Array.from(select.options).forEach(opt=>{
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'chip';
      chip.dataset.value = opt.value;
      chip.setAttribute('role', 'radio');
      const icon = select === fStatus
        ? '<span class="chip-dot" style="background:' + (statusColor[opt.value] || '#94a3b8') + '"></span>'
        : '<i class="ph ' + (CHIP_ICONS[opt.value] || 'ph-tag') + '"></i>';
      chip.innerHTML = icon + '<span>' + opt.textContent + '</span>';
      chip.addEventListener('click', ()=>{
        if(select.value === opt.value) return;
        select.value = opt.value;
        select.dispatchEvent(new Event('change', { bubbles: true }));
        syncChipPickers();
      });
      picker.appendChild(chip);
    });
  }
