  document.getElementById('sidebar-close').addEventListener('click', closeSidebar);

  // ---------- Developer suggestions with logos ----------
  // Typing in "Developer" lists matching developers already on the map, each
  // with the logos used on their projects. Picking a name fills it in; picking
  // a logo fills the name AND uses that logo for this project (saved like an
  // upload). Built from the pins in memory, so it's instant and offline-safe.
  const devSuggest = document.getElementById('dev-suggest');
  const normDev = (s)=> String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  let devList = [], devActive = -1;
  function developerIndex(){
    const byName = new Map();
    pins.forEach(p=>{
      const name = (p.developer || '').trim();
      if(!name) return;
      const key = normDev(name);
      let d = byName.get(key);
      if(!d){ d = { name, count: 0, logos: new Map() }; byName.set(key, d); }
      d.count++;
      if(typeof p.image === 'string' && p.image){
        // Same picture on several projects = one logo (URLs carry a content hash).
        const k = (p.image.match(/[?&]v=([^&]+)/) || [])[1] || p.image;
        const l = d.logos.get(k);
        if(l) l.n++; else d.logos.set(k, { src: p.image, n: 1 });
      }
    });
    return [...byName.values()];
  }
  function hideDevSuggest(){
    devSuggest.hidden = true; devActive = -1;
    fDeveloper.setAttribute('aria-expanded', 'false');
  }
  function renderDevSuggest(){
    const q = normDev(fDeveloper.value);
    if(!q || current.kind !== 'pin'){ hideDevSuggest(); return; }
    // Every typed word must match the start of a word in the name ("lo" → Lodha,
    // not every "deveLOpers"; "kun sp" → Kundan Spaces).
    const qWords = q.split(' ');
    devList = developerIndex()
      .filter(d=>{ const words = normDev(d.name).split(' '); return qWords.every(qw=> words.some(w=> w.startsWith(qw))); })
      .sort((a, b)=> (normDev(b.name).startsWith(q) - normDev(a.name).startsWith(q)) || b.count - a.count)
      .slice(0, 6);
    // Nothing to suggest, or the only match is exactly what's typed and has no logo.
    if(!devList.length || (devList.length === 1 && normDev(devList[0].name) === q && !devList[0].logos.size)){ hideDevSuggest(); return; }
    devActive = -1;
    devSuggest.innerHTML = devList.map((d, i)=>{
      const logos = [...d.logos.values()].sort((a, b)=> b.n - a.n).slice(0, 4);
      return '<div class="ds-row" role="option" data-i="' + i + '">'
        + '<button type="button" class="ds-name" data-i="' + i + '"><b>' + escapeHtml(d.name) + '</b><small>'
        + d.count + ' project' + (d.count === 1 ? '' : 's') + (logos.length ? '' : ' · no logo yet') + '</small></button>'
        + '<div class="ds-logos">' + logos.map(l=>
            '<button type="button" class="ds-logo" data-i="' + i + '" data-src="' + escapeHtml(l.src) + '" title="Use this logo">'
            + '<img src="' + escapeHtml(pinThumb(l.src)) + '" alt="' + escapeHtml(d.name) + ' logo" loading="lazy"></button>').join('')
        + '</div></div>';
    }).join('') + '<div class="ds-foot"><i class="ph ph-hand-tap"></i> Tap a logo to use it for this project</div>';
    devSuggest.hidden = false;
    fDeveloper.setAttribute('aria-expanded', 'true');
  }
  function pickDeveloper(i){
    const d = devList[i];
    if(!d) return;
    fDeveloper.value = d.name;
    hideDevSuggest();
    scheduleAutosave(0);
  }
  async function useDeveloperLogo(i, src){
    pickDeveloper(i);
    try{
      setStatus('saving', 'Adding logo…');
      const res = await fetch(src, { credentials: 'same-origin' });
      if(!res.ok) throw new Error('HTTP ' + res.status);
      const dataUrl = await resizeImage(await res.blob());
      imgPreview.src = dataUrl; imgPreview.style.display = 'block'; imgPlaceholder.style.display = 'none';
      imgPreview.dataset.pending = dataUrl;
      scheduleAutosave(0);
    }catch(err){
      console.error('Developer logo failed:', err);
      setStatus('error', 'Could not load that logo — upload it instead', 4000);
    }
  }
  fDeveloper.addEventListener('input', renderDevSuggest);
  fDeveloper.addEventListener('focus', renderDevSuggest);
  fDeveloper.addEventListener('blur', ()=> setTimeout(hideDevSuggest, 150));
  fDeveloper.addEventListener('keydown', (e)=>{
    if(devSuggest.hidden) return;
    const rows = devSuggest.querySelectorAll('.ds-row');
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
      e.preventDefault();
      devActive = (devActive + (e.key === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length;
      rows.forEach((r, k)=> r.classList.toggle('active', k === devActive));
    } else if(e.key === 'Enter' && devActive >= 0){
      e.preventDefault(); pickDeveloper(devActive);
    } else if(e.key === 'Escape'){
      hideDevSuggest();
    }
  });
  // Keep focus in the input while clicking a suggestion, so blur doesn't close it first.
  devSuggest.addEventListener('mousedown', (e)=> e.preventDefault());
  devSuggest.addEventListener('click', (e)=>{
