  // ---------- Autosave ----------
  // Every edit in the sidebar saves itself to Supabase ~0.8s after you stop
  // typing (instantly for dropdowns, toggles and image uploads). Saves run
  // one at a time so a slow network can't make an older save land last.
  // The public map picks each save up live through its realtime channel.
  let autosaveTimer = null;
  let saveChain = Promise.resolve();
  function scheduleAutosave(delay){
    if(!isAuthed || !current.kind) return;
    clearTimeout(autosaveTimer);
    setStatus('saving', 'Editing… autosave on');
    autosaveTimer = setTimeout(()=>{ autosaveTimer = null; queueSave(); }, delay == null ? 800 : delay);
  }
  function cancelAutosave(){ clearTimeout(autosaveTimer); autosaveTimer = null; }
  function queueSave(){
    // saveCurrent reads the form synchronously when it starts, so snapshot
    // the target now and run it after any save already in flight.
    const snapshot = { kind: current.kind, id: current.id };
    const job = saveChain.then(()=> saveCurrent(snapshot));
    saveChain = job.catch(()=>{});
    return job;
  }

  async function saveCurrent(target){
    target = target || current;
    if(!target.kind) return true;
    if(!requireAuth()) return false;
    if((target.kind === 'bridge' || target.kind === 'road') && fInfraType.value === '__add_new__'){
      setStatus('error','Finish creating the new type first (or pick an existing one)', 3000);
      return false;
    }
    setStatus('saving','Saving…');
    if(target.kind === 'pin'){
      const pin = pins.find(p=>p.id===target.id);
      if(!pin) return true;
      const patch = {
        title: fTitle.value.trim(), type: fType.value, status: fStatus.value, hidden: !fPublic.checked,
        price: fPrice.value.trim(), description: fDesc.value.trim(),
        developer: fDeveloper.value.trim(), location: fLocation.value.trim(), key_usp: fKeyUsp.value.trim(),
        rera_number: normRera(fRera.value),
        configuration: fConfiguration.value.trim(), sqft: fSqft.value.trim(),
        possession_timeline: fPossession.value.trim(), launch_date: fLaunchDate.value.trim(),
        whats_available: fWhatsAvailable.value.trim(), youtube_video_url: fVideoUrl.value.trim(),
        brochure_width: fBrochureWidth.value ? parseInt(fBrochureWidth.value, 10) : null,
        brochure_height: fBrochureHeight.value ? parseInt(fBrochureHeight.value, 10) : null,
        highlighted: fHighlight.checked, size: fPinSize.value,
        field_visibility: {
          name: fFieldVisName.checked,
          developer: fFieldVisDeveloper.checked, location: fFieldVisLocation.checked,
          type: fFieldVisType.checked, configuration: fFieldVisConfiguration.checked,
          price: fFieldVisPrice.checked, possession: fFieldVisPossession.checked,
          key_usp: fFieldVisUsp.checked, rera: fFieldVisRera.checked, status: fFieldVisStatus.checked,
          enquire: fFieldVisEnquire.checked, whatsapp: fFieldVisWhatsapp.checked
        },
        custom_fields: collectCustomFields()
      };
      // Pin number — only saved when it's a valid whole number that no
      // other pin is already using.
      const wantedNumber = parseInt(fNumber.value, 10);
      let numberClash = false;
      if(Number.isInteger(wantedNumber) && wantedNumber > 0 && wantedNumber !== pin.number){
        if(pins.some(p=> p.id !== pin.id && p.number === wantedNumber)) numberClash = true;
        else patch.number = wantedNumber;
      }
      if(imgPreview.dataset.pending){ patch.image = imgPreview.dataset.pending; delete imgPreview.dataset.pending; }
      if(brochurePreview.dataset.pending){ patch.brochure_image = brochurePreview.dataset.pending; delete brochurePreview.dataset.pending; }
      const { error } = await sb.from('pins').update(patch).eq('id', pin.id);
      if(error){ setStatus('error',saveFailMsg(error), 6000); return false; }
      Object.assign(pin, patch);
      renderPin(pin);
      if(current.kind === 'pin' && current.id === pin.id) sTitle.textContent = `Pin #${pin.number}`;
      if(numberClash){ setStatus('error', `Pin #${wantedNumber} already exists — pick an unused number`, 4000); return false; }
    } else if(target.kind === 'bridge'){
      const b = bridges.find(x=>x.id===target.id);
      if(!b) return true;
      const patch = { title: fTitle.value.trim(), notes: fDesc.value.trim(), type: fInfraType.value, size: fInfraSize.value, color: fInfraColor.value };
      if(infraIconPreview.dataset.pending){ patch.icon_image = infraIconPreview.dataset.pending; delete infraIconPreview.dataset.pending; }
      else if(infraIconPreview.dataset.removed){ patch.icon_image = null; delete infraIconPreview.dataset.removed; }
      const { error } = await sb.from('infra_markers').update(patch).eq('id', b.id);
      if(error){ setStatus('error',saveFailMsg(error), 6000); return false; }
      Object.assign(b, patch);
      renderBridge(b);
    } else if(target.kind === 'road'){
      const r = roads.find(x=>x.id===target.id);
      if(!r) return true;
      const patch = { title: fTitle.value.trim(), notes: fDesc.value.trim(), type: fInfraType.value, color: fInfraColor.value, weight: roadWeights[fInfraSize.value] || roadWeights.medium };
      const { error } = await sb.from('roads').update(patch).eq('id', r.id);
      if(error){ setStatus('error',saveFailMsg(error), 6000); return false; }
      Object.assign(r, patch);
      renderRoad(r);
    }
    setStatus('', 'Autosaved — live on the map', 1500);
    return true;
  }

  // Any typing / dropdown / toggle inside the sidebar triggers autosave.
  const sidebarBody = document.getElementById('sidebar-body');
  sidebarBody.addEventListener('input', (e)=>{
    if(e.target.closest('#wrap-new-infra-type')) return; // new-type form has its own button
    if(e.target.type === 'file') return;                   // handled after resize
    if(e.target.value === '__add_new__') return;           // still creating a type
    const instant = e.target.tagName === 'SELECT' || e.target.type === 'checkbox';
    scheduleAutosave(instant ? 0 : 800);
  });
  sidebarBody.addEventListener('change', (e)=>{
    if(e.target.closest('#wrap-new-infra-type') || e.target.type === 'file' || e.target.value === '__add_new__') return;
    if(e.target.tagName === 'SELECT' || e.target.type === 'checkbox') scheduleAutosave(0);
  });

  // "Done" saves anything still pending, then closes the panel.
  document.getElementById('btn-save').addEventListener('click', async ()=>{
    if(!requireAuth()) return;
    cancelAutosave();
    const ok = await queueSave();
    if(ok) closeSidebar();
  });

  const wrapNewInfraType = document.getElementById('wrap-new-infra-type');
  const fNewTypeLabel = document.getElementById('field-new-type-label');
  const fNewTypeEmoji = document.getElementById('field-new-type-emoji');
  const fNewTypeColor = document.getElementById('field-new-type-color');

  fInfraType.addEventListener('change', ()=>{
    if(fInfraType.value === '__add_new__'){
      wrapNewInfraType.style.display = '';
      fNewTypeLabel.value = '';
