  function waitForTiles(){
    return new Promise(resolve=>{
      let done = false;
      const finish = ()=>{ if(done) return; done = true; resolve(); };
      activeTiles.once('load', finish);
      setTimeout(finish, 1400);
      setTimeout(finish, 3200);
    });
  }
  function loadImg(src){
    return new Promise(resolve=>{
      const im = new Image();
      im.crossOrigin = 'anonymous';
      im.onload = ()=> resolve(im);
      im.onerror = ()=> resolve(null);
      im.src = src;
    });
  }
  function roundRect(ctx,x,y,w,h,r){
    ctx.beginPath();
    ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
    ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
  }
  function drawPin(ctx, p, pin, img){
    const color = statusColor[pin.status] || statusColor.available;
    const cx = p.x, cy = p.y - 31, r = 15;
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(p.x-7, p.y-22); ctx.lineTo(p.x+7, p.y-22); ctx.lineTo(p.x, p.y-3);
    ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.fillStyle=color; ctx.fill();
    ctx.lineWidth=2; ctx.strokeStyle='rgba(255,255,255,0.9)'; ctx.stroke();
    if(img){
      ctx.save();
      ctx.beginPath(); ctx.arc(cx,cy,r-1,0,Math.PI*2); ctx.clip();
      const d=(r-1)*2, s=Math.max(d/img.width, d/img.height);
      const iw=img.width*s, ih=img.height*s;
      ctx.drawImage(img, cx-iw/2, cy-ih/2, iw, ih);
      ctx.restore();
      const label=String(pin.number);
      ctx.font='700 9px Inter, Arial, sans-serif';
      const bw=Math.max(14, ctx.measureText(label).width+8), bh=13;
      const bx=cx+r-8, by=cy-r-5;
      ctx.fillStyle='#2c3644'; roundRect(ctx,bx,by,bw,bh,6); ctx.fill();
      ctx.lineWidth=1.5; ctx.strokeStyle='#fff'; ctx.stroke();
      ctx.fillStyle='#fff'; ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(label, bx+bw/2, by+bh/2+0.5);
    } else {
      ctx.fillStyle='#fff'; ctx.font='700 12px Inter, Arial, sans-serif';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText(String(pin.number), cx, cy);
    }
    ctx.restore();
  }
  function drawInfra(ctx, p, b){
    const meta = infraTypes[b.type] || infraTypes.bridge;
    const sz = infraSizes[b.size] || infraSizes.medium;
    const color = b.color || meta.color;
    const s = sz.px, x = p.x - s/2, y = p.y - s;
    ctx.save();
    ctx.fillStyle=color; roundRect(ctx, x, y, s, s, 8); ctx.fill();
    ctx.lineWidth=2; ctx.strokeStyle='#fff'; ctx.stroke();
    ctx.font = sz.font + 'px "Segoe UI Emoji","Apple Color Emoji","Noto Color Emoji",sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText(meta.emoji, x + s/2, y + s/2 + 1);
    ctx.restore();
  }

  const downloadBtn = document.getElementById('btn-download-image');
  downloadBtn.addEventListener('click', async ()=>{
    downloadBtn.disabled = true;
    setStatus('saving','Preparing image…');
    try{
      const pts = [];
      boundary.forEach(c=> pts.push(c));
      pins.forEach(p=> pts.push([p.lat, p.lng]));
      bridges.forEach(b=> pts.push([b.lat, b.lng]));
      if(pts.length) map.fitBounds(L.latLngBounds(pts), {padding:[70,70], animate:false});
      await waitForTiles();

      const size = map.getSize();
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const out = document.createElement('canvas');
      out.width = Math.round(size.x*dpr); out.height = Math.round(size.y*dpr);
      const ctx = out.getContext('2d');
      ctx.scale(dpr, dpr);
      ctx.fillStyle = '#f8fafc'; ctx.fillRect(0,0,size.x,size.y);

      const mapRect = map.getContainer().getBoundingClientRect();
      map.getContainer().querySelectorAll('img.leaflet-tile').forEach(img=>{
        if(!img.complete || img.naturalWidth===0 || img.style.display==='none' || img.style.opacity==='0') return;
        const r = img.getBoundingClientRect();
        try{ ctx.drawImage(img, r.left-mapRect.left, r.top-mapRect.top, r.width, r.height); }catch(e){}
      });

      roads.forEach(r=>{
        if(!r.points || r.points.length < 2) return;
        const meta = infraTypes[r.type] || infraTypes.proposed_road;
        ctx.save();
        ctx.beginPath();
        r.points.forEach((c,i)=>{
          const q = map.latLngToContainerPoint(L.latLng(c[0], c[1]));
          i===0 ? ctx.moveTo(q.x,q.y) : ctx.lineTo(q.x,q.y);
        });
        ctx.lineJoin='round'; ctx.lineCap='round';
        ctx.lineWidth = r.weight || 5;
        ctx.strokeStyle = r.color || meta.color;
        if(r.type === 'proposed_road') ctx.setLineDash([10,8]);
        if(r.type === 'metro_line') ctx.setLineDash([7,5]);
        ctx.stroke(); ctx.setLineDash([]);
        ctx.restore();
      });

      if(boundary && boundary.length>1){
        ctx.save();
        ctx.beginPath();
        boundary.forEach((c,i)=>{
          const q = map.latLngToContainerPoint(L.latLng(c[0], c[1]));
          i===0 ? ctx.moveTo(q.x,q.y) : ctx.lineTo(q.x,q.y);
        });
        ctx.closePath();
        ctx.fillStyle='rgba(231,76,60,0.03)'; ctx.fill();
        ctx.setLineDash([5,5]); ctx.lineWidth=2.5; ctx.strokeStyle='#e74c3c';
        ctx.stroke(); ctx.setLineDash([]);
        ctx.restore();
      }

      bridges.forEach(b=> drawInfra(ctx, map.latLngToContainerPoint(L.latLng(b.lat,b.lng)), b));
      const imgs = await Promise.all(pins.map(p=> p.image ? loadImg(p.image) : Promise.resolve(null)));
      pins.forEach((pin,i)=> drawPin(ctx, map.latLngToContainerPoint(L.latLng(pin.lat,pin.lng)), pin, imgs[i]));

      out.toBlob(blob=>{
        if(!blob){ setStatus('error','Could not build image — check tiles loaded, try again', 2800); downloadBtn.disabled=false; return; }
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'mundhwa-map-' + new Date().toISOString().slice(0,10) + '.png';
        a.click();
        setTimeout(()=> URL.revokeObjectURL(a.href), 4000);
        setStatus('', 'All changes saved — synced', 2000);
        downloadBtn.disabled = false;
      }, 'image/png');
    }catch(err){
      console.error('image capture failed', err);
      setStatus('error','Image capture failed — try again', 2800);
      downloadBtn.disabled = false;
    }
  });

  document.getElementById('search-input').addEventListener('keydown', (e)=>{
    if(e.key !== 'Enter') return;
    const q = e.target.value.trim().toLowerCase();
    if(!q) return;
    const match = pins.find(p => String(p.number) === q || (p.title||'').toLowerCase().includes(q));
    if(match){
      map.setView([match.lat, match.lng], 17, {animate:true});
      pinMarkers.get(match.id).openPopup();
    } else {
      setStatus('error', 'No matching pin found');
      setTimeout(()=> setStatus('', 'All changes saved — synced'), 2000);
    }
  });

  async function reloadPins(){
    if(isEditingLocally) return;
