  // ---------- Google Analytics click tracking ----------
  // Delegated listener catches every toolbar/UI button click in one place —
  // covers Add Project, Add Infrastructure, Draw Road/Metro/Boundary, Lock
  // buttons, Leads, Satellite, Export, Sign in, and the Cards Data
  // toggle — without needing a tracking call wired into each handler.
  // Pin, infra marker, and road clicks are tracked individually above since
  // they carry more useful labels (title/type) than a generic button id.
  document.addEventListener('click', (e)=>{
    const btn = e.target.closest('.btn, #btn-auth');
    if(!btn || !btn.id) return;
    trackEvent('toolbar', 'click', btn.id);
  });

  sb.channel('pins-changes').on('postgres_changes', {event:'*', schema:'public', table:'pins'}, reloadPins).subscribe();
  sb.channel('infra-changes').on('postgres_changes', {event:'*', schema:'public', table:'infra_markers'}, reloadInfra).subscribe();
  sb.channel('roads-changes').on('postgres_changes', {event:'*', schema:'public', table:'roads'}, reloadRoads).subscribe();
  sb.channel('settings-changes').on('postgres_changes', {event:'*', schema:'public', table:'map_settings'}, reloadSettings).subscribe();


  // ---------- Map tools sidebar: dock / icon rail / drawer ----------
  (function setupToolsSidebar(){
    const body = document.body;
    // Inside the super-admin (iframe) the admin already has a header, so the
    // editor drops its own once signed in and gives that space to the map.
    let embedded = false;
    try{ embedded = window.self !== window.top; }catch(e){ embedded = true; }
    body.classList.toggle('embedded', embedded);

    // Google "search any location" is a large script — load it only when the
    // tools are first opened, or once the browser is idle after start-up.
    const PLACES_SRC = "https://maps.googleapis.com/maps/api/js?key=AIzaSyDNOgozjUkI3JB3q9k8_I07-10TrgX83EU&libraries=places&loading=async&callback=initGooglePlaces";
    let placesRequested = false;
    function loadPlaces(){
      if(placesRequested) return;
      placesRequested = true;
      const el = document.createElement('script');
      el.src = PLACES_SRC; el.async = true;
      document.head.appendChild(el);
    }
    const idle = window.requestIdleCallback || ((cb)=> setTimeout(cb, 1));
    setTimeout(()=> idle(loadPlaces), 6000);
    const toggleBtn = document.getElementById('tools-toggle');
    const closeBtn = document.getElementById('tools-close');
    const collapseBtn = document.getElementById('tools-collapse');
    const backdrop = document.getElementById('tools-backdrop');
    const toolbarEl = document.getElementById('toolbar');
    const drawerMq = window.matchMedia('(max-width: 1024px)');
    const RAIL_KEY = 'mg_editor_tools_rail';
    // Leaflet must re-measure the map once the sidebar has finished moving.
    const refit = ()=> setTimeout(()=> map.invalidateSize({ pan: false }), 260);

    function setDrawer(open){
      if(open) loadPlaces();
      body.classList.toggle('tools-open', open);
      toggleBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
    // A small round button on the sidebar's edge opens / closes it (no hover).
    const edgeBtn = document.createElement('button');
    edgeBtn.type = 'button';
    edgeBtn.id = 'tools-edge';
    edgeBtn.setAttribute('aria-controls', 'toolbar');
    document.getElementById('topbar').appendChild(edgeBtn);
    function updateCollapseBtn(){
      const open = !body.classList.contains('tools-rail');
      edgeBtn.innerHTML = open ? '<i class="ph ph-caret-left"></i>' : '<i class="ph ph-caret-right"></i>';
      edgeBtn.title = open ? 'Close sidebar' : 'Open sidebar';
      edgeBtn.setAttribute('aria-label', edgeBtn.title);
      edgeBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
    function setRail(on){
      body.classList.toggle('tools-rail', on);
      if(!on) body.classList.remove('tools-peek');
      updateCollapseBtn();
      try{ localStorage.setItem(RAIL_KEY, on ? '1' : '0'); }catch(e){}
      refit();
    }
    // Closed (icon strip) is the default; the open/closed choice is remembered.
    let startRail = true;
    try{ startRail = localStorage.getItem(RAIL_KEY) !== '0'; }catch(e){}
    body.classList.toggle('tools-rail', startRail);
    updateCollapseBtn();

    edgeBtn.addEventListener('click', ()=>{ const open = body.classList.contains('tools-rail'); if(open) loadPlaces(); setRail(!open); });
    toolbarEl.addEventListener('focusin', loadPlaces);

    toggleBtn.addEventListener('click', ()=> setDrawer(!body.classList.contains('tools-open')));
    closeBtn.addEventListener('click', ()=> setDrawer(false));
    backdrop.addEventListener('click', ()=> setDrawer(false));
    document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape' && body.classList.contains('tools-open')) setDrawer(false); });
    // In the drawer, picking a tool closes it so the map is free to use
    // (e.g. to place a pin or draw a road). Search and toggles keep it open.
    toolbarEl.addEventListener('click', (e)=>{
      if(drawerMq.matches && e.target.closest('.tb-group .btn')) setDrawer(false);
    });
    drawerMq.addEventListener('change', ()=>{ setDrawer(false); refit(); });
    refit();
  })();

})();

// The location-search box now lives on its own row under the toolbar
// (styled via CSS), so it no longer needs JS to float it next to the
// pin-search field. Kept as a no-op so existing callers stay valid, and
// any stale inline coords from an earlier build get cleared.
function positionPlaceSearchSlot(){
  const slot = document.getElementById('place-search-slot');
  if(!slot) return;
  slot.style.top = slot.style.left = slot.style.height = '';
}
window.addEventListener('resize', positionPlaceSearchSlot);
window.addEventListener('load', positionPlaceSearchSlot);
const toolbarElForSlot = document.getElementById('toolbar');
if(toolbarElForSlot) toolbarElForSlot.addEventListener('scroll', positionPlaceSearchSlot);
positionPlaceSearchSlot();

function initGooglePlaces(){
  async function setup(){
    const slot = document.getElementById('place-search-slot');
    if(!slot || !window.google || !google.maps.importLibrary) return;
    try{
      await google.maps.importLibrary('places');
      const placeAutocomplete = new google.maps.places.PlaceAutocompleteElement({
        includedRegionCodes: ['in']
      });
      placeAutocomplete.placeholder = '🌍 Search any location…';
      slot.appendChild(placeAutocomplete);
      positionPlaceSearchSlot();
      placeAutocomplete.addEventListener('gmp-select', async (event) => {
        try{
          const place = event.placePrediction.toPlace();
          await place.fetchFields({ fields: ['location', 'displayName'] });
          if(place.location && window.flyToSearchedPlace){
            window.flyToSearchedPlace(place.location.lat(), place.location.lng());
          }
        }catch(err){ console.error('Place selection error:', err); }
      });
    }catch(err){ console.error('Google Places failed to load:', err); }
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', setup);
  } else {
    setup();
  }
}
